def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= 100:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = (sum(prev_bids) / len(prev_bids)) if prev_bids else 0.0

    scarcity = (25.0 - float(supply)) / 10.0
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    danger = 0.0
    if hp <= 2:
        danger += 1.0
    elif hp <= 4:
        danger += 0.55
    if no_water_days >= 1:
        danger += 0.8

    base = 24.0 + 20.0 * scarcity + 10.0 * danger

    if float(supply) <= 16.0:
        base += 18.0
    elif float(supply) >= 22.0:
        base -= 8.0

    if urgent_opp >= 2:
        base += 8.0
    if rich_opp >= 2:
        base += 6.0

    if highest_prev >= 170.0:
        if hp > 4 and no_water_days == 0 and float(supply) >= 19.0:
            bid = 16.0
        else:
            bid = max(base + 10.0, 92.0)
    elif highest_prev >= 130.0:
        if hp > 5 and no_water_days == 0 and float(supply) >= 20.0:
            bid = max(base - 6.0, 20.0)
        else:
            bid = max(base, min(highest_prev * 0.78, highest_prev - 8.0))
    elif highest_prev >= 80.0:
        bid = max(base, avg_prev + 3.0)
    elif highest_prev > 0.0:
        bid = max(base, highest_prev + 2.0)
    else:
        bid = base

    if hp <= 2 or no_water_days >= 1:
        bid = max(bid, 88.0 + 14.0 * scarcity)

    if day >= 8:
        bid += 6.0

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = 10.0
    max_affordable = max(0.0, budget - reserve)
    if max_affordable <= 0.0:
        max_affordable = budget

    bid = min(bid, max_affordable)
    if bid < 0.0:
        bid = 0.0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], 10.0)

    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]

    avg_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 20.0

    if my_status['hp'] <= 3:
        return min(my_status['budget'], max(avg_bid * 1.2, 50.0))

    return min(my_status['budget'], max(avg_bid * 0.9, 15.0))
